    title: "When in Debt",
    keywords: "strength",
    aliases: "Supplication When in Debt",
    additionalCategories: [],
    text: "اللَّهُمَّ اكْفِنِى بِحَلاَلِكَ عَنْ حَرَامِكَ وَأَغْنِنِى بِفَضْلِكَ عَمَّنْ سِوَاكَ",
    meaning: "O Allah, suffice me with what is lawful and keep me away from what is unlawful, and enrich me with Your bounty so I do not depend on anyone besides You.",
    collectionReference: "HR. at-Tirmidzi No. 2563",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/daily-dua/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-daily-dua-31",
    category: "strength",
    title: "For Protection from Laziness, Sadness, and Debt",
    keywords: "strength guidance",
    aliases: "Supplication for Protection from Laziness, Sadness, and Debt Dua To Be Released From Debt, Anxiety, Weakness, Laziness, Fear, And Pressure from Others",
    additionalCategories: ["guidance"],
    text: "اَللّٰهُمَّ إِنِّى أَعُوْذُبِكَ مِنَ الْهَمِّ وَالْحَزْنِ وَأَعُوْذُبِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَأَعُوْذُبِكَ مِنَ الْجُبْنِ وَالْبُخْلِ وَأَعُوْذُبِكَ مِنْ غَلَبَتِ الدَّيْنِ وَقَهْرِ الرجال",
    meaning: "O Allah, I seek refuge in You from anxiety and grief, and I seek refuge in You from incapacity and laziness, and I seek refuge in You from cowardice and miserliness, and I seek refuge in You from being overpowered by debt and from being overcome by men.",
    collectionReference: "HR. Abu Dawud No. 1555",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/daily-dua/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-daily-dua-32",
    category: "home",
    title: "After Sneezing",
    keywords: "home",
    aliases: "Supplication After Sneezing",
    additionalCategories: [],
    text: "الحَمْدُ للهِ",
    meaning: "All praise is to Allah.",
    collectionReference: "HR. al-Bukhari",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/daily-dua/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-daily-dua-33",
    category: "home",
    title: "Upon Hearing Someone Sneeze",
    keywords: "home",
    aliases: "Supplication Upon Hearing Someone Sneeze",
    additionalCategories: [],
    text: "يَرْحَمُكَ اللهُ",
    meaning: "May Allah have mercy on you.",
    collectionReference: "HR. al-Bukhari",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/daily-dua/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-daily-dua-34",
    category: "home",
    title: "Response to Someone Who Says 'Yarhamukallah' After You Sneeze",
    keywords: "home",
    aliases: "Response to Someone Who Says 'Yarhamukallah' After You Sneeze",
    additionalCategories: [],
    text: "يَهْدِيكُمُ اللهُ وَيُصْلِحُ بَالَكُمْ",
    meaning: "May Allah guide you and improve your condition.",
    collectionReference: "HR. al-Bukhari",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/daily-dua/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-daily-dua-35",
    category: "guidance",
    title: "For Good Character",
    keywords: "guidance",
    aliases: "Supplication for Good Character",
    additionalCategories: [],
    text: "اللَّهُمَّ كَمَا حَسَّنْتَ خَلْقِي فَحَسِّنْ خُلُقِي",
    meaning: "O Allah, just as You have made my external form good, make my character good as well.",
    collectionReference:
        "HR. Ahmad, authenticated by al-Albani in al-Irwa', 1/115",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/daily-dua/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-daily-dua-36",
    category: "protection",
    title: "For Protection from Satan",
    keywords: "protection",
    aliases: "Prayer for Protection from Satan",
    additionalCategories: [],
    text: "رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِيْنِ وَأَعُوْذُ بِكَ رَبِّ أَنْ يَحْضُرُوْنِ",
    meaning: "My Lord, I seek refuge in You from the whispers of Satan, and I seek refuge in You, my Lord, from their presence around me.",
    collectionReference: "QS. Al-Mu'minun: 97-98",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/daily-dua/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-daily-dua-37",
    category: "prayer",
    title: "After the Adhan",
    keywords: "prayer",
    aliases: "Prayer After the Adhan",
    additionalCategories: [],
    text: "اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ",
    meaning: "O Allah, Lord of this perfect call and the established prayer, grant Muhammad the wasilah (a high status in Paradise) and the excellence (above all creation), and raise him to the praiseworthy station that You have promised him.",
    collectionReference: "Narrated by Abu Dawud (529), at-Tirmidhi (211), an-Nasa'i (2:26), Ibn Majah (722)",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/daily-dua/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-5",
    category: "morning",
    title: "Upon Entering The Morning by Asking for Protection from Allah",
    keywords: "morning",
    aliases: "Upon Entering The Morning by Asking for Protection from Allah",
    additionalCategories: [],
    text: "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ. رَبِّ أَسْأَلُكَ خَيْرَ مَا فِيْ هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيْ هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَسُوْءِ الْكِبَرِ، رَبِّ أَعُوْذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ",
    meaning: "We have entered the morning and the dominion belongs to Allah, and all praise is for Allah. There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs the dominion and to Him is praise, and He is over all things competent. My Lord, I ask You for the good of this day and the good of what follows it, and I seek refuge in You from the evil of this day and the evil of what follows it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from the punishment of the Fire and the punishment of the grave.",
    collectionReference: "HR. Muslim No. 2723 (75), Abu Dawud No. 5071, and at-Tirmidzi 3390, sahih from Abdullah Ibn Mas'ud",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-6",
    category: "morning",
    title: "Upon Entering The Morning with The Grace of Allah",
    keywords: "morning",
    aliases: "Upon Entering The Morning with The Grace of Allah",
    additionalCategories: [],
    text: "اَللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوْتُ وَإِلَيْكَ النُّشُوْرُ",
    meaning: "O Allah, with Your grace and help we enter the morning, and with Your grace and help we enter the evening. By Your grace and will we live and by Your grace and will we die. And to You is the resurrection (for all creatures).",
    collectionReference: "HR. al-Bukhari in al-Adab al-Mufrad No. 1199, this wording is the wording of al-Bukhari, at-Tirmidzi No. 3391, Abu Dawud No. 5068, Ahmad 11/354, Ibn Majah No. 3868",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-8",
    category: "morning",
    title: "For Protection and Good Health",
    keywords: "morning evening",
    aliases:
        "Dua for Protection and Good Health Prayer for Health and Protection",
    additionalCategories: ["evening"],
    text: "اَللَّهُمَّ عَافِنِيْ فِيْ بَدَنِيْ ، اَللَّهُمَّ عَافِنِيْ فِيْ سَمْعِيْ ، اَللَّهُمَّ عَافِنِيْ فِيْ بَصَرِيْ ، لَا إِلَـهَ إِلَّا أَنْتَ ، اَللَّهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْكُفْرِوَالْفَقْرِ ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ ، لَا إِلَـهَ إِلَّا أَنْتَ",
    meaning: "O Allah, protect my body (from illness and from what I do not want). O Allah, protect my hearing (from illness and disobedience or from what I do not want). O Allah, protect my sight, there is no deity worthy of worship except You. O Allah, indeed I seek refuge in You from disbelief and poverty. I seek refuge in You from the punishment of the grave, there is no deity worthy of worship except You.",
    collectionReference: "HR. al-Bukhari in Sahih al-Adab al-Mufrad No. 701, Abu Dawud No. 5090, Ahmad V/42, hasan",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-9",
    category: "morning",
    title: "For Salvation in The World and Hereafter",
    keywords: "morning evening",
    aliases: "Dua for Salvation in The World and Hereafter Prayer for Safety in This World and the Hereafter",
    additionalCategories: ["evening"],
    text: "اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَاْلآخِرَةِ، اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ اللَّهُمَّ اسْتُرْ عَوْرَاتِى وَآمِنْ رَوْعَاتِى. اَللَّهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِيْ، وَعَنْ يَمِيْنِيْ وَعَنْ شِمَالِيْ، وَمِنْ فَوْقِيْ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ",
    meaning: "O Allah, indeed I ask You for well-being and safety in this world and the Hereafter. O Allah, indeed I ask You for well-being and safety in my religion, my world, my family and my wealth. O Allah, cover my flaws (faults and things that are not appropriate for others to see) and calm me from fear. O Allah, protect me from the front, behind, right, left and above me. I seek refuge in Your greatness, so that I am not snatched from below me (by snakes or swallowed by the earth, etc., which would cause me to fall).",
    collectionReference: "HR. al-Bukhari in al-Adab al-Mufrad No. 1200, Abu Dawud No. 5074, an-Nasa'i VII/282, Ibn Majah No. 3871, al-Hakim 1/517-518, and others from Ibn Umar radhiyallahu 'anhuma",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-10",
    category: "morning",
    title: "For Protection from Shaytan Whispers",
    keywords: "morning evening",
    aliases: "Dua for Protection from Shaytan Whispers Prayer for Seeking Protection from the Whispers of Satan",
    additionalCategories: ["evening"],
    text: "اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَاوَاتِ وَاْلأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيْكَهُ، أَشْهَدُ أَنْ لاَ إِلَـهَ إِلاَّ أَنْتَ، أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِيْ سُوْءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ",
    meaning: "O Allah, Knower of the unseen and the seen, Creator of the heavens and the earth, Lord of all things and their Sovereign. I bear witness that there is no deity worthy of worship except You. I seek refuge in You from the evil of myself, Satan and his soldiers (temptations to commit shirk against Allah), and I (seek refuge in You) from committing evil against myself or dragging it to a Muslim.",
    collectionReference: "HR. al-Bukhari in al-Adab al-Mufrad No. 1202, at-Tirmidzi No. 3392 and Abu Dawud No. 5067",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-11",
    category: "morning",
    title: "Asking for Protection from All Harms",
    keywords: "morning evening",
    aliases: "Asking for Protection from All Harms Remembrance to Be Protected from All Dangers",
    additionalCategories: ["evening"],
    text: "بِسْمِ اللَّهِ الَّذِى لاَ يَضُرُّ مَعَ اسْمِهِ شَىْءٌ فِى الأَرْضِ وَلاَ فِى السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ",
    meaning: "In the name of Allah with Whose name nothing can harm on earth or in heaven, and He is the All-Hearing, All-Knowing.",
    collectionReference: "HR. at-Tirmidzi No. 3388, Abu Dawud No. 5088, Ibn Majah No. 3869, al-Hakim 1/514, and Ahmad No. 446 and 474",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-12",
    category: "morning",
    title: "Declaration of Pleasure with Allah, Islam, and the Prophet Muhammad sallallahu 'alayhi wa sallam",
    keywords: "morning evening",
    aliases: "Declaration of Pleasure with Allah, Islam, and the Prophet Muhammad sallallahu 'alayhi wa sallam Declaration of Contentment with Allah, Islam, and the Prophet Muhammad sallallahu 'alayhi wa sallam",
    additionalCategories: ["evening"],
    text: "رَضِيْتُ بِاللهِ رَبًّا، وَبِاْلإِسْلاَمِ دِيْنًا، وَبِمُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا",
    meaning: "I am pleased with Allah as my Lord, Islam as my religion and Muhammad sallallahu 'alayhi wa sallam as my Prophet (sent by Allah).",
    collectionReference: "HR. Ahmad IV/337, Abu Dawud No. 5072, at-Tirmidzi No. 3389, Ibn Majah No. 3870, an-Nasa'i in 'Amalul Yaum wal Lailah No. 4 and Ibnus Sunni No. 68",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-13",
    category: "morning",
    title: "Asking Allah for Guidance",
    keywords: "morning evening",
    aliases: "Asking Allah for Guidance  Asking for Guidance from Allah",
    additionalCategories: ["evening"],
    text: "يَا حَيُّ يَا قَيُّوْمُ بِرَحْمَتِكَ أَسْتَغِيْثُ، وَأَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ وَلاَ تَكِلْنِيْ إِلَى نَفْسِيْ طَرْفَةَ عَيْنٍ أَبَدًا",
    meaning: "O Ever-Living, O Self-Sustaining, by Your mercy I seek help, rectify all my affairs and do not leave me to myself even for the blink of an eye.",
    collectionReference: "HR. an-Nasa'i in 'Amalul Yaum wal Lailah No. 575, and al-Hakim 1/545, Sahih at-Targhib wat Tarhib 1/417 No. 661, As-Sahihah No. 227, hasan • HR. an-Nasa'i in 'Amalul Yaum wal Lailah No. 575, and al-Hakim 1/545, see Sahih at-Targhib wat Tarhib 1/417 No. 661, As-Sahihah No. 227, hasan",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-14",
    category: "morning",
    title: "Entering The Morning Upon The Natural Religion of Islam",
    keywords: "morning",
    aliases: "Entering The Morning Upon The Natural Religion of Islam",
    additionalCategories: [],
    text: "أَصْبَحْنَا عَلَى فِطْرَةِ اْلإِسْلاَمِ وَعَلَى كَلِمَةِ اْلإِخْلاَصِ، وَعَلَى دِيْنِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِيْنَا إِبْرَاهِيْمَ، حَنِيْفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِيْنَ",
    meaning: "In the morning we are upon the fitrah of Islam, the word of sincerity (the testimony of faith), the religion of our Prophet Muhammad, sallallahu 'alayhi wa sallam, and the religion of our father Abraham, who stood upon the straight path, a Muslim, and was not among the polytheists.",
    collectionReference: "HR. Ahmad III/406, 407, ad-Darimi II/292 and Ibnus Sunni in Amalul Yaum wal Lailah No. 34, Mishkat al-Masabih No. 2415, Sahih al-Jami' as-Saghir No. 4674, sahih",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-15",
    category: "morning",
    title: "Tawheed Dhikr",
    keywords: "morning evening prayer",
    aliases: "Tawheed Dhikr Remembrance of the Oneness of Allah There is No Partner for Allah, and To Him Belongs All Things",
    additionalCategories: ["evening", "prayer"],
    text: "لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ",
    meaning: "There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs the dominion and all praise. And He is over all things competent.",
    collectionReference: "HR al-Bukhari No. 3293 and 6403, Muslim IV/2071 No. 2691 (28), at-Tirmidzi No. 3468, Ibn Majah No. 3798 • Sharh Shahih Muslim, 5: 84",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/morning-dhikr/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-morning-dhikr-16",
    category: "morning",
    title: "Read Tasbih",
    keywords: "morning evening",
    aliases: "Read Tasbih Reciting Praise to Allah",
    additionalCategories: ["evening"],
    text: "سُبْحَانَ اللهِ وَبِحَمْدِهِ عَدَدَ خَلْقَهِ وَرِضَى نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ",
