    category: "evening",
    title: "For Protection from the Evil of Allah's Creation",
    keywords: "evening",
    aliases: "Prayer for Protection from the Evil of Allah's Creation",
    additionalCategories: [],
    text: "أَعُوْذُ بِكَلِمَاتِ اللهِ التَّآمَّاتِ مِنْ شَرِّ مَا خَلَقَ",
    meaning: "I seek refuge in the perfect words of Allah from the evil of what He has created.",
    collectionReference: "HR. Ahmad 11/290, an-Nasa'i in 'Amalul Yaum wal Lailah No. 596, Sahih at-Targhib wat Tarhib 1/412 No. 652, Sahih al-Jami' as-Saghir No. 6427",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/evening-dhikr/en.json",
