  DuaEntry.text(
    id: "fitrahive-dhikr-after-salah-2",
    category: "prayer",
    title: "Allah, The Giver of Peace",
    keywords: "prayer",
    aliases: "Allah, The Giver of Peace",
    additionalCategories: [],
    text: "اَللَّهُمَّ أَنْتَ السَّلاَمُ، وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا الْجَلاَلِ وَاْلإِكْرَامِ",
    meaning: "O Allah, You are Peace, and from You is peace. Blessed are You, O Possessor of majesty and honor.",
    collectionReference: "HR. Muslim No. 591",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/dhikr-after-salah/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-dhikr-after-salah-3",
    category: "prayer",
    title: "Allah, The Preventer and The Giver of All Things",
    keywords: "prayer",
    aliases: "Allah, The Preventer and The Giver of All Things",
    additionalCategories: [],
    text: "لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ، اَللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ",
    meaning: "There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs dominion and praise, and He is over all things competent. O Allah, there is no preventer of what You give, and no giver of what You withhold, and wealth and honor do not benefit their possessor (except faith and righteous deeds that save from punishment). Only from You is wealth and honor.",
    collectionReference: "HR. Bukhari No. 844 and Muslim No. 593",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/dhikr-after-salah/en.json",
  ),
  DuaEntry.text(
    id: "fitrahive-dhikr-after-salah-4",
    category: "prayer",
    title: "Allah, The Possessor of All and The Only One Worthy of Worship",
    keywords: "prayer",
    aliases: "Allah, The Possessor of All and The Only One Worthy of Worship",
    additionalCategories: [],
    text: "لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ. لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللهِ، لاَ إِلَـهَ إِلاَّ اللهُ، وَلاَ نَعْبُدُ إِلاَّ إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لاَ إِلَـهَ إِلاَّ اللهُ مُخْلِصِيْنَ لَهُ الدِّيْنَ وَلَوْ كَرِهَ الْكَافِرُوْنَ",
    meaning: "There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs dominion and praise, and He is over all things competent. There is no power and no strength except by Allah. There is no deity worthy of worship except Allah, and we do not worship except Him. To Him belongs all favor, grace, and good praise. There is no deity worthy of worship except Allah, making our religion sincerely for Him, even if the disbelievers dislike it.",
    collectionReference: "HR. Muslim No. 594",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/dhikr-after-salah/en.json",
  ),
