  DuaEntry.text(
    id: "fitrahive-selected-dua-5",
    category: "guidance",
    title: "To Seek Refuge Against The Loss Of Pleasure",
    keywords: "guidance",
    aliases: "Dua To Seek Refuge Against The Loss Of Pleasure",
    additionalCategories: [],
    text: "اللَّهُمَّ إِنِّى أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ",
    meaning: "O Allah, I seek refuge in You from the loss of the pleasures that You have bestowed, from changes in the health that You have bestowed, from Your sudden torment, and from all Your wrath.",
    collectionReference: "HR. Muslim No. 2739",
    collectionUrl: "https://github.com/fitrahive/dua-dhikr/blob/f42f895f914319a844c3e3c2279483cae060ea19/data/dua-dhikr/selected-dua/en.json",
